    \resumeItem{Created a Git-based GCP training workflow by tracking engineering blogs and industry trends, and collaborated on code reviews for frontend frameworks, ensuring clean, maintainable changes while tuning models.}
  \resumeItemListEnd

\resumeSubheading
  {Software Engineer Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Coded Python services for TENEX.AI, handling 11K concurrent connections with 12 ms avg response, integrating REST APIs and optimizing backend performance to support full-stack feature delivery.}
    \resumeItem{Built full-stack features using Python, integrating REST APIs and databases; handled 9+ concurrent services to improve reliability and performance across student-facing applications at IIT Indore.}
    \resumeItem{Wrote Python services on GCP at IIT Indore, staying up-to-date with the latest technologies and industry trends; validated across 8 experimental conditions, cutting deployment steps from 18.}
